import {SECTIONS,DIFFICULTIES,MODES,KEY,slug,fresh,budget,latest,stats,matches,queue,sessionKey,makeSession,recordAnswer,nextQuestion,migrate,merge,fingerprint,hash,validState,selfGraded,cleanResponse,toggleStrike,unstrike,setHighlights,esc} from './core.js';
import {rangeOffsets,applyHighlights,overlaps,preview,gridIn,GRID_DIRECTIONS,REFERENCE,lineReader} from './tools.js';
import {load,item,clean} from './content.js';
import {syncCode,setSyncCode,newCode,normalizeCode,formatCode,push,pull,syncMeta,setSyncMeta} from './sync.js';
import {mirror,idbGet,idbPut,snapshots,requestPersistence,persisted} from './storage.js';
const $=s=>document.querySelector(s), letters=['A','B','C','D'];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5v16m0-16C8 2 4 3 2 4v15c4-1 7 0 10 2 3-2 6-3 10-2V4c-3-1-6-2-10 1z"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8M8 11h.01M12 11h.01M16 11h.01M8 15h.01M12 15h.01M16 15h.01M8 19h.01M12 19h4"/>',history:'<path d="M3 12a9 9 0 1 0 3-6.7L3 8"/><path d="M3 3v5h5M12 7v5l3 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',flag:'<path d="M5 21V4m0 0h11l-2 4 2 4H5"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
// College Board's exam configuration of the Desmos graphing calculator, as used in Bluebook.
const ZOOMS=[.85,1,1.15,1.3,1.5,1.75,2],DESMOS='https://www.desmos.com/testing/collegeboard/graphing', PREFS_KEY='reading-room-prefs';
let questions=[],byId=new Map(),state=fresh(),route={view:'home'},activeKey=null,peek=null,detailText=false,error='',lastTick=performance.now(),storageOK=true,corruptRaw=null,shownSelf=null,historyFilter={section:'All',result:'All',limit:50};
let prefs={difficulty:'All',mode:'new',calc:true,calcWidth:520,...readJSON(PREFS_KEY)};
let toastTimer,mirrorTimer,dock=null,readerOn=false,lastRaw=null,syncTimer,syncing=false,syncStatus={state:'idle'};
function readJSON(key){try{return JSON.parse(localStorage.getItem(key));}catch{return null;}}
function writeJSON(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}

// Saving: localStorage on every change, IndexedDB mirror right away for answers and within 2 seconds otherwise.
// If another tab saved since this one last read or wrote, its progress is merged in first, never overwritten.
function absorb(raw){const other=raw&&raw!==lastRaw&&parseState(raw);lastRaw=raw;if(!other)return false;const before=state.attempts.length;state=merge(state,other);if(activeKey&&!state.sessions[activeKey])activeKey=null;return state.attempts.length!==before;}
function save(important=false){if(corruptRaw)return false;let ok=true,raw=null;try{raw=localStorage.getItem(KEY);}catch{}const gained=raw!==lastRaw&&absorb(raw);
 state.savedAt=Date.now();const json=JSON.stringify(state);try{localStorage.setItem(KEY,json);lastRaw=json;}catch{ok=false;}if(gained)queueMicrotask(()=>{render();toast('Progress from another tab was added.');});
 clearTimeout(mirrorTimer);if(important)mirror(json);else mirrorTimer=setTimeout(()=>mirror(JSON.stringify(state)),2000);
 if(!ok&&storageOK)toast('Progress could not be saved in this browser. Export a backup before closing.');storageOK=ok;return ok;}
function commit(fn,important=true){if(corruptRaw){toast('Export the unreadable saved data, then restore a valid backup in Settings.');return false;}const before=structuredClone(state);fn();if(!save(important)){state=before;return false;}scheduleSync();return true;}
// Sync across browsers: upload after changes (batched), on load, every minute, and when the tab is shown or hidden.
function scheduleSync(delay=3000){if(!syncCode())return;clearTimeout(syncTimer);syncTimer=setTimeout(syncNow,delay);}
async function syncNow(){const code=syncCode();if(!code||corruptRaw||syncing)return;syncing=true;syncStatus={...syncStatus,state:'syncing'};showSync();
 try{const meta=syncMeta(code),mine=hash(fingerprint(state)),changed=mine!==meta.sent,reply=changed?await push(code,state):await pull(code,meta.version),remote=reply.state,other=remote&&parseState(remote);
  if(remote&&!other)throw Error('The synced copy does not match this question collection.');
  // Only a real change is uploaded; otherwise a version check that is a few bytes when nothing is new.
  if(other){const was=JSON.stringify({...state,savedAt:0});state=merge(state,other);save(true);if(JSON.stringify({...state,savedAt:0})!==was&&!$('dialog[open]:not(#ref-dialog)')&&!notePop)render();}// Record what the server now holds, so anything changed here while the request was in flight still uploads next time.
  setSyncMeta({code,version:reply.version,sent:other?hash(fingerprint(other)):changed?mine:meta.sent});syncStatus={state:'ok',at:Date.now()};}
 catch(e){syncStatus={state:'error',at:syncStatus.at,message:navigator.onLine===false?'You are offline. Progress is still saved here and will sync when you reconnect.':e.message};}
 finally{syncing=false;showSync();}}
function syncLine(){const code=syncCode();if(!code)return 'Saved on this browser';return syncStatus.state==='error'?'Sync paused':syncStatus.state==='syncing'?'Syncing…':syncStatus.at?`Synced ${new Date(syncStatus.at).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}`:'Sync on';}
function showSync(){const el=$('#sync-line');if(el)el.textContent=syncLine();const st=$('#sync-status');if(st)st.textContent=syncStatus.state==='error'?syncStatus.message:syncLine();}
function parseState(raw){try{const s=migrate(typeof raw==='string'?JSON.parse(raw):raw);return validState(s,questions)?s:null;}catch{return null;}}
async function loadState(){let raw=null;try{raw=localStorage.getItem(KEY);}catch{storageOK=false;}
 const mirrored=await idbGet('latest'),local=raw&&parseState(raw),backup=mirrored&&parseState(mirrored);
 if(raw){try{if(JSON.parse(raw).version===1&&!localStorage.getItem(KEY+'-pre-v2')){localStorage.setItem(KEY+'-pre-v2',raw);await idbPut('pre-v2',raw);}}catch{}}
 const best=local&&backup?merge(local,backup):local||backup;
 if(best){state=best;lastRaw=raw;if(!local&&raw){await idbPut('unreadable-'+Date.now(),raw);toast('Saved progress was damaged, so it was restored from the automatic backup copy.');}save(true);}
 else if(raw){corruptRaw=raw;error='Saved progress could not be read. The original browser data has not been changed. Export it or restore a backup in Settings before practicing.';}}

const sec=id=>SECTIONS[id], domainsOf=s=>Object.keys(sec(s).domains);
const inSection=(s,domain='All',skill='All')=>questions.filter(q=>matches(q,{section:s,domain,skill}));
function pct(s){return s.accuracy===null?'—':`${s.accuracy}%`;}
function bar(s){return `<div class="bar" role="img" aria-label="${s.right} correct, ${s.wrong} incorrect, ${s.total-s.done} unanswered"><span class="good" style="width:${s.total?s.right/s.total*100:0}%"></span><span class="bad" style="width:${s.total?s.wrong/s.total*100:0}%"></span></div>`;}
function time(n){const v=Math.ceil(n);return `${Math.floor(v/60)}:${String(v%60).padStart(2,'0')}`;}
function heading(kicker,title,description,action=''){return `<header class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</header>`;}
const href=(...parts)=>'#'+parts.filter(Boolean).map(slug).join('/');
function nav(){const wrong=stats(questions,state.attempts).wrong,current=route.view==='section'||route.view==='domain'?route.section:route.view==='practice'?state.sessions[activeKey]?.options.section:route.view;
 return `<aside class="sidebar"><a class="brand" href="#home" aria-label="Reading Room home"><span class="brandmark">r<span>.</span></span><span>reading room<small>SAT PRACTICE</small></span></a><div class="nav-label">YOUR WORKSPACE</div><nav aria-label="Main navigation">${[['home','grid','Home'],['rw','book','Reading & Writing'],['math','calc','Math'],['history','history','Past questions'],['review','save','Review'],['settings','settings','Settings']].map(([id,i,label])=>`<a href="#${id}" class="nav-item ${current===id?'selected':''}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='review'&&wrong?`<span class="nav-count">${wrong}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-dot ${storageOK?'':'off'}"></div><span>${storageOK?'Saved automatically':'Not saving'}<small><span id="sync-line">${syncLine()}</span> · ${state.attempts.length} answers</small></span><button class="icon-button" data-action="export" aria-label="Export progress backup">${icon('download')}</button></div></aside>`;}

function lastIn(section){return Object.entries(state.sessions).filter(([,v])=>!v.complete&&(!section||v.options.section===section)).sort((a,b)=>b[1].updatedAt-a[1].updatedAt)[0];}
function sessionLabel(o){return [sec(o.section).short,o.domain==='All'?'All domains':o.domain,o.skill==='All'?null:o.skill].filter(Boolean).join(' · ');}
function continueBanner(section){const found=lastIn(section);if(!found)return '';const [key,s]=found,q=byId.get(s.ids[s.index]);return `<section class="continue-banner"><div class="round-icon">${icon(s.options.section==='math'?'calc':'book')}</div><div><span class="eyebrow">PICK UP WHERE YOU LEFT OFF</span><h3>${esc(sessionLabel(s.options))}</h3><p>Question ${s.index+1} of ${s.ids.length} · ${esc(q.k)}${s.revealed?' · answered':s.choice>=0||s.response?' · answer in progress':''}</p></div><button class="primary" data-resume="${esc(key)}">Continue ${icon('arrow')}</button></section>`;}
function statCards(qs){const s=stats(qs,state.attempts);return `<section class="stats-grid" aria-label="Practice statistics">${[['Questions completed',s.done,`of ${s.total} available`],['Accuracy',pct(s),'based on your latest answers'],['Correct answers',s.right,'questions answered correctly'],['To revisit',s.wrong,'questions to work on next']].map(([label,value,note],i)=>`<div class="stat-card"><span>${label}</span><strong class="${i===2?'green':i===3?'rust':''}">${value}</strong><small>${note}</small></div>`).join('')}</section>`;}
function weekPanel(){const counts=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const date=d.toDateString(),attempts=state.attempts.filter(a=>new Date(a.at).toDateString()===date);counts.push({label:d.toLocaleDateString(undefined,{weekday:'short'}),n:attempts.length,right:attempts.filter(a=>a.correct).length});}const max=Math.max(5,...counts.map(x=>x.n));
 return `<section class="panel"><div class="section-heading"><div><h2>This week</h2><p>${counts.reduce((n,d)=>n+d.n,0)} answers in the last 7 days</p></div>${icon('clock')}</div><div class="activity-chart" aria-label="Daily answer counts">${counts.map(d=>`<div class="day"><span>${d.n}</span><div class="day-track"><div class="day-bar" style="height:${d.n/max*100}%" title="${d.label}: ${d.n} answers"><span style="height:${d.n?d.right/d.n*100:0}%"></span></div></div><small>${d.label}</small></div>`).join('')}</div><div class="chart-note">All attempts, including repeat practice</div></section>`;}
function attemptTable(list,{section=true}={}){return `<div class="table-scroll"><table><thead><tr><th>When</th>${section?'<th>Section</th>':''}<th>Skill</th><th>Difficulty</th><th>Your answer</th><th>Result</th><th>Time</th><th></th></tr></thead><tbody>${list.map(a=>{const q=byId.get(a.id);return `<tr><td>${new Date(a.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</td>${section?`<td>${sec(q.s).short}</td>`:''}<td>${esc(q.k)}</td><td><span class="level ${q.l.toLowerCase()}">${q.l}</span></td><td>${a.response!==undefined?esc(a.response):letters[a.choice]}</td><td><span class="result ${a.correct?'correct':'incorrect'}">${a.correct?'Correct':'Incorrect'}</span></td><td>${a.seconds}s</td><td><button class="text-button" data-inspect="${q.id}" data-at="${a.at}">Review ↗</button></td></tr>`;}).join('')}</tbody></table></div>`;}

function home(){const cards=Object.entries(SECTIONS).map(([id,S])=>{const qs=inSection(id),s=stats(qs,state.attempts),found=lastIn(id);return `<article class="section-card"><div class="card-top"><span class="round-icon">${icon(id==='math'?'calc':'book')}</span><span class="badge">${qs.length} questions</span></div><h2>${S.name}</h2><p>${domainsOf(id).length} domains · ${Object.values(S.domains).flat().length} skills</p>${bar(s)}<div class="module-meta"><span>${s.done} / ${s.total} completed</span><span>${pct(s)} accuracy</span></div><div class="button-row"><a class="primary" href="#${id}">Open ${S.short} ${icon('arrow')}</a>${found?`<button class="secondary" data-resume="${esc(found[0])}">Continue</button>`:''}</div></article>`;}).join('');
 return `${heading('YOUR OVERVIEW','A little practice. Real progress.','Every answer saves automatically, so you can close the page and pick up exactly where you left off.')}${statCards(questions)}${continueBanner()}<div class="sections-grid">${cards}</div><div class="dashboard-columns"><section class="panel"><div class="section-heading"><div><h2>Performance by difficulty</h2><p>Latest answer per question. Unanswered questions excluded.</p></div></div><table class="difficulty-table"><thead><tr><th>Difficulty</th>${Object.values(SECTIONS).map(S=>`<th>${S.short}</th>`).join('')}</tr></thead><tbody>${DIFFICULTIES.slice(1).map(d=>`<tr><th><span class="level ${d.toLowerCase()}">${d}</span></th>${Object.keys(SECTIONS).map(id=>{const ds=stats(questions.filter(q=>q.s===id&&q.l===d),state.attempts);return `<td>${pct(ds)} <small class="muted">${ds.right}/${ds.done}</small>${bar({...ds,total:ds.done})}</td>`;}).join('')}</tr>`).join('')}</tbody></table></section>${weekPanel()}</div><section class="panel recent"><div class="section-heading"><div><h2>Recent answers</h2><p>${state.attempts.length} total attempts</p></div><a class="text-button" href="#history">All past questions ${icon('arrow')}</a></div>${state.attempts.length?attemptTable(state.attempts.slice(-6).reverse()):`<div class="empty-inline">${icon('book')}<h3>Your next chapter starts here.</h3><p>Choose a section, then a domain and a skill. Your results will appear here.</p></div>`}</section>`;}

function sectionPage(id){const S=sec(id),qs=inSection(id);return `${heading(S.name.toUpperCase(),S.name,`Choose a domain, then a skill. ${S.paceNote}${id==='math'?' · Desmos graphing calculator built in.':'.'}`)}${statCards(qs)}${continueBanner(id)}<div class="section-heading"><div><h2>Domains</h2><p>Each domain and skill keeps its own saved place.</p></div></div><div class="modules-grid">${domainsOf(id).map((d,i)=>{const dq=inSection(id,d),s=stats(dq,state.attempts);return `<a class="module-card" href="${href(id,d)}"><div class="card-top"><span class="module-number">0${i+1}</span><span class="badge">${dq.length} questions</span></div><h3>${d}</h3><p>${S.domains[d].length} skills</p>${bar(s)}<div class="module-meta"><span>${s.done} / ${s.total} completed</span><span>${pct(s)} accuracy</span></div><span class="secondary full">Choose a skill ${icon('arrow')}</span></a>`;}).join('')}</div>`;}

function chips(name,options,value){return `<div class="chips" role="group" aria-label="${name}">${options.map(([v,label])=>`<button class="chip ${v===value?'on':''}" data-pref="${name}" data-value="${v}" aria-pressed="${v===value}">${label}</button>`).join('')}</div>`;}
function domainPage(id,domain){const S=sec(id),opts=skill=>({section:id,domain,skill,difficulty:prefs.difficulty,mode:prefs.mode});
 const row=(skill,label)=>{const all=inSection(id,domain,skill),s=stats(all,state.attempts),o=opts(skill),key=sessionKey(o),saved=state.sessions[key],n=queue(questions,state,o).length,resume=saved&&!saved.complete;
  return `<div class="skill-row ${skill==='All'?'all':''}"><div><strong>${esc(label)}</strong><small>${all.length} questions · ${s.done} completed · ${pct(s)} accuracy</small>${bar(s)}</div><div class="skill-action"><small>${resume?`Saved at ${saved.index+1} of ${saved.ids.length}`:`${n} ${prefs.mode==='new'?'new':'matching'}`}</small><button class="${resume?'primary':'secondary'}" data-start="${esc(key)}" ${!resume&&!n?'disabled':''}>${resume?'Continue':'Start'} ${icon('arrow')}</button></div></div>`;};
 return `<div class="practice-toolbar"><a class="text-button" href="#${id}">← ${S.name}</a></div>${heading(S.name.toUpperCase(),esc(domain),'Pick a skill to practice. Your place in each one is saved separately.')}<section class="panel"><div class="filter-bar"><label>Difficulty${chips('difficulty',DIFFICULTIES.map(d=>[d,d]),prefs.difficulty)}</label><label>Questions${chips('mode',MODES,prefs.mode)}</label></div><div class="skill-list">${row('All',`All ${domain} skills`)}${S.domains[domain].map(k=>row(k,k)).join('')}</div></section>`;}

// Question rendering, shared by practice and the review dialog.
const cleaned=new Map();
function html(id,field,value){const k=id+field;if(!cleaned.has(k))cleaned.set(k,clean(value));return cleaned.get(k);}
function paper(q,it){if(q.p===-1)return `<div class="paper-toolbar"><span>COLLEGE BOARD · ${q.id}</span><button class="text-button" data-action="text">${detailText?'Original view':'Text view'}</button></div>${detailText?`<div class="passage" data-annot="passage">${esc(it.passage)}</div><p class="question-prompt">${esc(it.prompt)}</p><p class="text-warning">For graphs, tables, and underlined text, use Original view.</p>`:it.images.map((src,i)=>`<img class="question-image" src="${esc(src)}" alt="Original College Board question ${q.id}, page ${i+1}, including any charts and formatting. Text version is available." /><a class="image-zoom" href="${esc(src)}" target="_blank" rel="noreferrer">Open original at full size ↗</a>`).join('')}`;
 return `<div class="paper-toolbar"><span>COLLEGE BOARD · ${q.id}</span></div>${it.stimulus?`<div class="q-html stimulus" data-annot="stimulus">${html(q.id,'stimulus',it.stimulus)}</div>`:''}${q.s==='math'||!it.stimulus?`<div class="q-html stem" data-annot="stem">${html(q.id,'stem',it.stem)}</div>`:''}`;}
function prompt(q,it){return q.p===-1?`<p class="answer-prompt" data-annot="prompt">${esc(it.prompt)}</p>`:q.s==='rw'&&it.stimulus?`<div class="q-html answer-prompt" data-annot="stem">${html(q.id,'stem',it.stem)}</div>`:'';}
function choiceText(q,it,i){return q.p===-1?esc(it.choices[i]):`<span class="q-html">${html(q.id,'choice'+i,it.choices[i])}</span>`;}
function answers(q,it,{choice=-1,response='',revealed=false,attempt=null,correct=attempt?.correct,readonly=false,struck=[],elim=false}){
 if(q.t==='mcq')return `<div class="choices" role="group" aria-label="Select one answer">${it.choices.map((c,i)=>{const x=struck.includes(i)&&!revealed;return `<div class="choice-row ${x?'struck':''}"><button class="choice ${choice===i?'chosen':''} ${revealed?(i===q.a?'is-correct':i===choice?'is-wrong':''):''}" ${readonly?'':`data-choice="${i}"`} aria-pressed="${choice===i}" ${revealed||readonly?'disabled':''}><span class="letter">${letters[i]}</span><span>${choiceText(q,it,i)}${revealed&&(i===q.a||i===choice)?`<small>${i===q.a?'Correct answer':'Your answer'}</small>`:''}</span></button>${elim&&!revealed&&!readonly?`<button class="strike" data-strike="${i}" aria-pressed="${x}" aria-label="${x?'Undo crossing out':'Cross out'} answer ${letters[i]}">${x?'Undo':`<s>${letters[i]}</s>`}</button>`:''}</div>`;}).join('')}</div>`;
 return `<div class="spr"><label for="spr-input">Your answer</label><input id="spr-input" class="${revealed?(correct?'is-correct':'is-wrong'):''}" value="${esc(response)}" maxlength="6" autocomplete="off" spellcheck="false" inputmode="text" ${revealed||readonly?'disabled':''} aria-describedby="spr-help"><small id="spr-help">Enter a number, decimal, or fraction such as 3/4. Up to 5 characters, or 6 with a negative sign.</small><div class="spr-preview" id="spr-preview" aria-live="polite">${response?`Answer preview: ${preview(response)}`:''}</div>${readonly||revealed?'':GRID_DIRECTIONS}${revealed?`<p class="spr-key">${q.a?`Accepted answer${q.a.length>1?'s':''}: <strong>${q.a.map(esc).join(' or ')}</strong>`:'Compare your answer with the explanation below.'}</p>`:''}</div>`;}
function explanation(q,it,correct){return `<div class="explanation ${correct?'correct':correct===null?'':'incorrect'}" tabindex="-1"><div class="feedback-title">${correct?'✓ Correct. Nicely done.':correct===null?'Check your work':q.t==='mcq'?`The correct answer is ${letters[q.a]}.`:'Not quite.'}</div><h3>Why this answer works</h3>${q.p===-1?`<p>${esc(it.explanation)}</p>`:`<div class="q-html">${html(q.id,'explanation',it.explanation)}</div>`}</div>`;}

function workspace(){const s=state.sessions[activeKey];if(!s){activeKey=null;return home();}
 const o=s.options,back=o.domain==='All'?`#${o.section}`:href(o.section,o.domain),math=o.section==='math';
 if(s.complete&&peek===null){const ss=stats(s.ids.map(id=>byId.get(id)),state.attempts);return `<div class="completion"><div class="success-icon">${icon('check')}</div><div class="eyebrow">SESSION COMPLETE</div><h1>One step further.</h1><p>${esc(sessionLabel(o))} · ${s.ids.length} questions</p><div class="completion-stats"><div><strong>${ss.right}</strong><span>Correct</span></div><div><strong>${ss.wrong}</strong><span>Incorrect</span></div><div><strong>${pct(ss)}</strong><span>Accuracy</span></div></div><p class="muted">Based on your latest answer to each question in this session.</p><div class="button-row"><a class="primary" href="${back}">Back to skills</a><button class="secondary" data-action="peek-last">Look back at these questions</button><button class="secondary" data-action="retry-session">Practice these again</button></div></div>`;}
 const view=peek??s.index,q=byId.get(s.ids[view]),it=item(q.id),past=view<s.index||s.complete,attempt=past?[...state.attempts].reverse().find(a=>a.id===q.id):null;
 if(!it){load(q).then(()=>render()).catch(e=>{error=e.message;render();});return `<div class="loading small-loading">Loading question…</div>`;}
 const next=byId.get(s.ids[view+1]);if(next)load(next).catch(()=>{});
 const choice=past?attempt?.choice??-1:s.choice,response=past?attempt?.response??'':s.response,revealed=past?!!attempt:s.revealed,correct=past?attempt?.correct:latest(state.attempts).get(q.id)?.correct,marked=state.bookmarks.includes(q.id),self=selfGraded(q);
 const actions=past?`<div class="button-row past-nav"><button class="secondary" data-action="peek-prev" ${view===0?'disabled':''}>← Previous</button>${s.complete&&view===s.ids.length-1?'':`<button class="secondary" data-action="peek-next">Next →</button>`}<button class="primary" data-action="peek-exit">${s.complete?'Session summary':'Back to current question'}</button></div>`
  :s.revealed?`<button class="primary full" data-action="next">${s.index===s.ids.length-1?'Finish session':'Next question'} ${icon('arrow')}</button>`
  :self&&shownSelf===q.id?`<div class="self-grade"><p>Compare your answer with the explanation, then mark it.</p><div class="button-row"><button class="primary" data-action="self-right">I got it right</button><button class="secondary" data-action="self-wrong">I got it wrong</button></div></div>`
  :`<button class="primary full" data-action="check" ${q.t==='mcq'?s.choice<0?'disabled':'':cleanResponse(s.response)?'':'disabled'}>${self?'Show answer':'Check answer'} ${icon('check')}</button>`;
 const answerPanel=`<section class="answer-panel" aria-label="Answer"><div class="answer-title"><h2>${past?'Your answer':q.t==='mcq'?'Choose an answer':'Enter your answer'}</h2><div class="answer-tools"><button class="mark-review ${marked?'on':''}" data-action="bookmark" data-id="${q.id}" aria-pressed="${marked}">${icon('flag')} Mark for Review</button>${q.t==='mcq'&&!revealed&&!past?`<button class="elim-toggle ${prefs.elim?'on':''}" data-action="elim" aria-pressed="${!!prefs.elim}" aria-label="Answer eliminator" title="Cross out answer choices"><s>ABC</s></button>`:''}</div></div>${prompt(q,it)}${answers(q,it,{choice,response,revealed,attempt,correct,readonly:past,struck:state.marks[q.id]?.x||[],elim:prefs.elim})}${revealed||(self&&shownSelf===q.id&&!past)?explanation(q,it,revealed?correct:null):''}${actions}${past?'':`<div class="keyboard-hint">${q.t==='mcq'?'A–D to choose · ':''}Enter to ${s.revealed?'continue':'check'}</div>`}</section>`;
 const paperPanel=`<section class="question-paper" aria-label="Question">${paper(q,it)}</section>`;
 const layout=math?`<div class="math-single">${paperPanel}${answerPanel}</div>`:`<div class="question-layout">${paperPanel}${answerPanel}</div>`;
 return `<div class="practice-toolbar"><a class="text-button" href="${back}">← ${esc(o.domain==='All'?sec(o.section).name:o.domain)}</a><div class="toolbar-right">${view>0&&!past?`<button class="text-button" data-action="peek-prev">← Previous questions</button>`:''}${zoomControl()}<button class="secondary tool ${readerOn?'on':''}" data-action="reader" aria-pressed="${readerOn}" title="Shade everything except the lines you are reading">Line reader</button>${math?`<button class="secondary tool" data-action="reference">Reference</button><button class="secondary calc-toggle ${prefs.calc?'on':''}" data-action="calc" aria-pressed="${prefs.calc}">${icon('calc')} ${prefs.calc?'Hide calculator':'Calculator'}</button>`:''}<span class="save-status">${storageOK?'● Saved automatically':'Save unavailable — export a backup'}</span></div></div><header class="question-heading"><div><div class="eyebrow">${esc(sessionLabel(o))}${past?' · PAST QUESTION':''}</div><h1>${esc(q.k)}</h1><p>Question ${view+1} of ${s.ids.length} <span class="dot-sep">·</span> <span class="level ${q.l.toLowerCase()}">${q.l}</span>${past&&attempt?` <span class="dot-sep">·</span> answered ${new Date(attempt.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`:''}</p></div>${past?'':`<div class="timer-card"><span>${icon('clock')} ${math?'SAT Math pace':state.pace==='average'?'SAT average pace':'Suggested skill pace'}</span><div><strong id="timer" class="${prefs.timerHidden?'concealed':''}">${time(s.remaining)}</strong><button class="text-button timer-vis" data-action="timer-vis">${prefs.timerHidden?'Show':'Hide'}</button><button class="icon-button" data-action="pause" ${s.revealed?'disabled':''} aria-label="${s.paused?'Resume':'Pause'} timer">${s.paused?'▶':'Ⅱ'}</button></div><small id="timer-note">${s.revealed?'Answer checked':s.paused?'Paused':s.remaining<=0?'Time reached · keep going':'No automatic submission'}</small></div>`}</header><div class="session-progress"><span style="width:${(s.index+(s.revealed?1:0))/s.ids.length*100}%"></span></div>${layout}`;}

function zoomControl(){const z=prefs.zoom||1,i=ZOOMS.indexOf(z);return `<div class="zoom-ctl" role="group" aria-label="Text size"><button data-action="zoom-out" aria-label="Smaller text" ${i<=0?'disabled':''}>A−</button><span>${Math.round(z*100)}%</span><button data-action="zoom-in" aria-label="Larger text" ${i>=ZOOMS.length-1?'disabled':''}>A+</button></div>`;}
function history(){const f=historyFilter,list=state.attempts.filter(a=>{const q=byId.get(a.id);return (f.section==='All'||q.s===f.section)&&(f.result==='All'||(f.result==='Correct')===a.correct);}).reverse();
 return `${heading('PAST QUESTIONS','Everything you have answered.','Every answer is saved the moment you check it. Open any question to see your answer, the correct answer, and the explanation.')}<section class="panel"><div class="filter-bar"><label>Section${chips('h-section',[['All','All'],...Object.entries(SECTIONS).map(([id,S])=>[id,S.short])],f.section)}</label><label>Result${chips('h-result',[['All','All'],['Correct','Correct'],['Incorrect','Incorrect']],f.result)}</label></div>${list.length?attemptTable(list.slice(0,f.limit))+(list.length>f.limit?`<div class="more"><button class="secondary" data-action="more">Show more (${list.length-f.limit} older)</button></div>`:''):'<p class="empty-small">No answers here yet.</p>'}</section>`;}
function review(){const map=latest(state.attempts),wrong=questions.filter(q=>map.has(q.id)&&!map.get(q.id).correct),marked=questions.filter(q=>state.bookmarks.includes(q.id)),groups=[...new Set(wrong.map(q=>q.s+'|'+q.d))];
 return `${heading('REVIEW','Turn mistakes into progress.','Revisit an answer, read the explanation, or practice the questions again.')}<section class="panel"><div class="section-heading"><div><h2>Questions to revisit <span class="badge">${wrong.length}</span></h2><p>Questions you got wrong on your latest attempt.</p></div></div>${reviewList(wrong)}<div class="review-actions">${groups.map(g=>{const [s,d]=g.split('|');return `<button class="secondary" data-start="${esc(sessionKey({section:s,domain:d,skill:'All',difficulty:'All',mode:'wrong'}))}">Practice ${esc(d)} ${icon('arrow')}</button>`;}).join('')}</div></section><section class="panel"><div class="section-heading"><div><h2>Marked for review <span class="badge">${marked.length}</span></h2><p>Questions you flagged for another look.</p></div></div>${reviewList(marked)}</section>`;}
function reviewList(qs){return qs.length?`<div class="review-list">${qs.map(q=>`<button class="review-row" data-inspect="${q.id}"><span class="mono">${q.id}</span><span><strong>${esc(q.k)}</strong><small>${sec(q.s).short} · ${esc(q.d)}</small></span><span class="level ${q.l.toLowerCase()}">${q.l}</span>${icon('arrow')}</button>`).join('')}</div>`:'<p class="empty-small">No questions here yet.</p>';}
function settings(){setTimeout(fillStorage);return `${heading('SETTINGS','Make room for your routine.','Simple controls for your practice and progress.')}<section class="panel settings-panel"><h2>Reading and Writing timer</h2><p>Choose your pacing target. Math always uses the SAT average of 95 seconds per question.</p><label class="radio-row"><input type="radio" name="pace" value="average" ${state.pace==='average'?'checked':''}><span><strong>SAT average · 71 seconds</strong><small>The Reading and Writing section has 54 questions in 64 minutes.</small></span></label><label class="radio-row"><input type="radio" name="pace" value="category" ${state.pace==='category'?'checked':''}><span><strong>Suggested skill pacing · 45–90 seconds</strong><small>Extra time for evidence and inference; less for vocabulary. These are practice targets, not official category limits.</small></span></label><p>The timer pauses when you leave practice or hide the tab. You can keep answering after it reaches zero.</p></section>${syncPanel()}<section class="panel settings-panel"><h2>Your progress</h2><p>Every choice, typed answer, timer and checked answer saves instantly to two separate stores in this browser, plus a daily snapshot for the last 14 days. Progress stays on this device and browser: it does not sync to other devices, and clearing this site's browser data removes it, so export a backup now and then.</p><div id="storage-status" class="storage-status">Checking storage…</div><div class="button-row"><button class="primary" data-action="export">${icon('download')} Export backup</button><button class="secondary" data-action="import">Restore backup</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><div id="snapshot-list"></div></section><section class="panel settings-panel"><h2>Your question collection</h2><p>${questions.length} official questions from your College Board question-bank exports.</p>${Object.entries(SECTIONS).map(([id,S])=>`<h3 class="source-heading">${S.name}</h3>${domainsOf(id).map(d=>`<div class="source-row"><span>${d}</span><strong>${inSection(id,d).length}</strong></div>`).join('')}`).join('')}<p class="small muted">Reading Room is an independent practice tool and is not affiliated with College Board. The graphing calculator is provided by Desmos.</p></section>`;}
function syncPanel(){const code=syncCode();return `<section class="panel settings-panel" id="sync-panel"><h2>Sync across browsers</h2>${code?`<p>Sync is on. Progress here is combined with every Chrome profile, browser, or device that uses this code. Answers are never dropped when copies are combined.</p><div class="sync-code"><code>${formatCode(code)}</code><button class="secondary" data-action="sync-copy">Copy code</button></div><p class="small muted" id="sync-status">${esc(syncStatus.state==='error'?syncStatus.message:syncLine())}</p><div class="button-row"><button class="secondary" data-action="sync-now">Sync now</button><button class="text-button" data-action="sync-off">Turn off on this browser</button></div>`
 :`<p>Use one sync code in each Chrome profile, browser, or device to share the same progress. Turning it on combines what is already saved here with what is saved under the code. Keep the code private: anyone who has it can see and change your progress.</p><div class="button-row"><button class="primary" data-action="sync-new">Turn on sync</button></div><label class="sync-join">Have a code from another browser?<span><input id="sync-input" placeholder="xxxx-xxxx-xxxx-…" autocomplete="off" spellcheck="false"><button class="secondary" data-action="sync-join">Use code</button></span></label>`}</section>`;}
async function fillStorage(){const el=$('#storage-status');if(!el)return;const p=await persisted(),snaps=await snapshots();el.innerHTML=p?'✓ This browser has agreed to keep Reading Room data even when storage runs low.':'This browser may clear site data when storage runs low. <button class="text-button" data-action="persist">Ask to keep it</button>';const list=$('#snapshot-list');if(list&&snaps.length)list.innerHTML=`<h3 class="source-heading">Automatic daily snapshots</h3>${snaps.map(k=>`<div class="source-row"><span>${k.slice(9)}</span><button class="text-button" data-snapshot="${k}">Restore</button></div>`).join('')}`;}

function render(focus=false){const body=route.view==='practice'?workspace():route.view==='section'?sectionPage(route.section):route.view==='domain'?domainPage(route.section,route.domain):route.view==='history'?history():route.view==='review'?review():route.view==='settings'?settings():home();
 $('#app').innerHTML=nav()+`<main id="main" class="${route.view==='practice'?'practicing':''}" style="--q-zoom:${prefs.zoom||1}" tabindex="-1">${error?`<div class="alert">${esc(error)}</div>`:''}${body}<footer>reading room <span>One question at a time.</span></footer></main>`;
 if(focus){window.scrollTo(0,0);$('#main').focus({preventScroll:true});}lastTick=performance.now();decorate();showCalc(route.view==='practice'&&state.sessions[activeKey]?.options.section==='math'&&!state.sessions[activeKey].complete&&prefs.calc);}
function parseRoute(){const [a,b]=location.hash.slice(1).split('/');if(SECTIONS[a]){const domain=b&&domainsOf(a).find(d=>slug(d)===b);return domain?{view:'domain',section:a,domain}:{view:'section',section:a};}return {view:['practice','history','review','settings'].includes(a)?a:'home'};}
function go(){tick();peek=null;shownSelf=null;if(readerOn){readerOn=false;lineReader(false);}closePops();const next=parseRoute();if(next.view==='practice'){activeKey=activeKey||state.lastSession;if(!state.sessions[activeKey]){location.replace('#home');return;}}else activeKey=null;route=next;render(true);}
function openSession(options,restart=false){tick();const key=sessionKey(options),old=state.sessions[key];if(!old||old.complete||restart){const ids=queue(questions,state,options);if(!ids.length){toast(options.mode==='new'?'You have answered every question here. Choose “All questions” to practice them again.':'No matching questions yet. Try another filter.');return;}if(!commit(()=>{state.sessions[key]=makeSession(ids,options,questions,state.pace);state.lastSession=key;}))return;}else if(!commit(()=>{state.lastSession=key;}))return;activeKey=key;if(location.hash==='#practice')go();else location.hash='#practice';}
function resume(key){if(!state.sessions[key])return;commit(()=>{state.lastSession=key;});activeKey=key;if(location.hash==='#practice')go();else location.hash='#practice';}
function tick(){const now=performance.now(),dt=Math.min(5,(now-lastTick)/1000);lastTick=now;const s=state.sessions[activeKey];if($('dialog[open]:not(#ref-dialog)')||route.view!=='practice'||peek!==null||!s||s.complete||s.revealed||s.paused||document.hidden)return;s.elapsed+=dt;s.remaining=Math.max(0,s.remaining-dt);save();const t=$('#timer');if(t)t.textContent=time(s.remaining);if(s.remaining===0&&$('#timer-note'))$('#timer-note').textContent='Time reached · keep going';}
function exportBackup(){const blob=new Blob([corruptRaw||JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`reading-room-progress-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress backup downloaded.');}
function replaceState(next,message){if(!confirm(`Replace this browser’s progress with ${next.attempts.length} saved answers? Export your current progress first if you want to keep it.`))return;const savedCorrupt=corruptRaw;corruptRaw=null;if(commit(()=>{state=next;})){error='';activeKey=null;go();toast(message);}else corruptRaw=savedCorrupt;}
async function inspect(id,at){tick();const q=byId.get(id),dialog=document.createElement('dialog');dialog.innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">${sec(q.s).short} · ${esc(q.k)} · ${q.id}</div><h2>Question review</h2></div><button class="icon-button" data-close aria-label="Close review">✕</button></div><div class="dialog-body"><p class="muted">Loading question…</p></div>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();lastTick=performance.now();});
 try{const it=await load(q),a=state.attempts.find(x=>x.id===id&&String(x.at)===at)||latest(state.attempts).get(id);dialog.querySelector('.dialog-body').innerHTML=`<div class="q-review ${q.s}">${paper(q,it)}${prompt(q,it)}${answers(q,it,{choice:a?.choice??-1,response:a?.response??'',revealed:true,attempt:a,readonly:true})}${explanation(q,it,a?a.correct:null)}${a?`<p class="muted small">Answered ${new Date(a.at).toLocaleString()} · ${a.seconds}s</p>`:''}</div>`;}catch(e){dialog.querySelector('.dialog-body').innerHTML=`<p class="alert">${esc(e.message)}</p>`;}}

// Desmos split screen. The calculator is docked outside the re-rendered markup, so moving between questions
// (or hiding it) keeps whatever you typed into it, as in the exam. Reloading the page starts it fresh.
function showCalc(open){if(!open&&!dock)return;if(!dock){dock=document.createElement('aside');dock.id='calc-dock';dock.setAttribute('aria-label','Desmos graphing calculator');dock.innerHTML=`<iframe title="Desmos graphing calculator" src="${DESMOS}" allow="clipboard-write"></iframe><div class="calc-divider" role="separator" aria-orientation="vertical" aria-label="Resize calculator" tabindex="0"></div>`;document.body.append(dock);}
 dock.hidden=!open;document.body.classList.toggle('calc-open',open);document.body.style.setProperty('--calc-w',Math.min(prefs.calcWidth,innerWidth*.6)+'px');}
function dragDivider(e){e.preventDefault();const d=e.target;d.setPointerCapture(e.pointerId);dock.classList.add('dragging');const left=dock.getBoundingClientRect().left,move=ev=>{prefs.calcWidth=Math.round(Math.min(innerWidth*.6,Math.max(300,ev.clientX-left)));document.body.style.setProperty('--calc-w',prefs.calcWidth+'px');},up=()=>{d.removeEventListener('pointermove',move);dock.classList.remove('dragging');writeJSON(PREFS_KEY,prefs);};d.addEventListener('pointermove',move);d.addEventListener('pointerup',up,{once:true});}
function nudgeDivider(e){if(!e.target.matches('.calc-divider')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();prefs.calcWidth=Math.round(Math.min(innerWidth*.6,Math.max(300,prefs.calcWidth+(e.key==='ArrowLeft'?-40:40))));writeJSON(PREFS_KEY,prefs);showCalc(true);}

// Highlights and notes on question text, the reference sheet, and closing exam-tool popovers.
let pop=null,notePop=null;
function currentId(){const s=state.sessions[activeKey];return route.view==='practice'&&s&&!(s.complete&&peek===null)?s.ids[peek??s.index]:null;}
function decorate(){const id=currentId();if(!id){closePops();return;}const list=(state.marks[id]?.h||[]).map((h,i)=>({...h,i}));for(const el of document.querySelectorAll('#main [data-annot]'))applyHighlights(el,list.filter(h=>h.f===el.dataset.annot));}
function closePops(){pop?.remove();pop=null;notePop?.remove();notePop=null;}
function checkSelection(){const sel=getSelection();if(notePop||!sel.rangeCount||sel.isCollapsed){pop?.remove();pop=null;return;}const r=sel.getRangeAt(0),node=r.commonAncestorContainer,el=(node.nodeType===1?node:node.parentElement)?.closest('[data-annot]');if(!el||!$('#main').contains(el)||!currentId()){pop?.remove();pop=null;return;}
 if(!pop){pop=document.createElement('button');pop.className='annot-pop';pop.textContent='Highlight & note';pop.addEventListener('pointerdown',e=>e.preventDefault());pop.addEventListener('click',addHighlight);document.body.append(pop);}
 const rect=r.getBoundingClientRect();pop.style.left=Math.max(8,rect.left+rect.width/2-60+scrollX)+'px';pop.style.top=Math.max(8,rect.top+scrollY-44)+'px';pop.target=el;}
function addHighlight(e){e.stopPropagation();const sel=getSelection(),el=pop?.target,id=currentId();if(!sel.rangeCount||!el||!id)return;const o=rangeOffsets(el,sel.getRangeAt(0));if(!o)return;const list=state.marks[id]?.h||[],h={f:el.dataset.annot,...o,n:''};
 if(overlaps(list,h)){toast('That text is already highlighted. Click the highlight to edit its note.');return;}sel.removeAllRanges();closePops();if(commit(()=>setHighlights(state,id,[...list,h]),false)){render();openNote(list.length);}}
function openNote(i){const id=currentId(),h=state.marks[id]?.h?.[i],mark=document.querySelector(`#main mark.hl[data-h="${i}"]`);if(!h||!mark)return;closePops();notePop=document.createElement('div');notePop.className='note-pop';notePop.setAttribute('role','dialog');notePop.setAttribute('aria-label','Highlight note');notePop.dataset.i=i;
 notePop.innerHTML=`<label>Note<textarea maxlength="2000" rows="3" placeholder="Add a note (optional)">${esc(h.n)}</textarea></label><div class="button-row"><button class="primary" data-note="save">Save</button><button class="secondary" data-note="delete">Remove highlight</button><button class="text-button" data-note="close">Close</button></div>`;
 document.body.append(notePop);const r=mark.getBoundingClientRect();notePop.style.left=Math.max(8,Math.min(innerWidth-310,r.left+scrollX))+'px';notePop.style.top=(r.bottom+scrollY+8)+'px';notePop.querySelector('textarea').focus();}
function noteAction(action){const i=Number(notePop?.dataset.i),id=currentId(),list=[...(state.marks[id]?.h||[])];if(id&&list[i]){if(action==='save')list[i]={...list[i],n:notePop.querySelector('textarea').value.slice(0,2000)};if(action==='delete')list.splice(i,1);if(action!=='close')commit(()=>setHighlights(state,id,list),false);}closePops();render();}
function reference(){let d=$('#ref-dialog');if(!d){d=document.createElement('dialog');d.id='ref-dialog';d.className='ref-dialog';d.innerHTML=`<div class="dialog-heading"><div><div class="eyebrow">SAT MATH</div><h2>Reference</h2></div><button class="icon-button" aria-label="Close reference">✕</button></div><div class="dialog-body">${REFERENCE}</div>`;document.body.append(d);d.querySelector('button').onclick=()=>d.close();}d.open?d.close():d.show();}
document.addEventListener('selectionchange',()=>requestAnimationFrame(checkSelection));
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;if(pop||notePop)closePops();else if($('#ref-dialog[open]'))$('#ref-dialog').close();else if(readerOn){readerOn=false;lineReader(false);render();}});
document.addEventListener('pointerdown',e=>{if(e.target.matches('.calc-divider'))dragDivider(e);});document.addEventListener('keydown',nudgeDivider);window.addEventListener('resize',()=>dock&&!dock.hidden&&showCalc(true));
document.addEventListener('click',e=>{if(notePop&&!e.target.closest('.note-pop'))closePops();const mk=e.target.closest('mark.hl');if(mk&&$('#main').contains(mk)&&!getSelection().toString()){openNote(Number(mk.dataset.h));return;}const btn=e.target.closest('button');if(!btn)return;
 if(btn.dataset.note){noteAction(btn.dataset.note);return;}
 if(btn.dataset.strike!==undefined){const id=currentId();if(id&&commit(()=>toggleStrike(state,id,Number(btn.dataset.strike)),false))render();return;}
 if(btn.dataset.start){openSession(JSON.parse(btn.dataset.start).reduce((o,v,i)=>({...o,[['section','domain','skill','difficulty','mode'][i]]:v}),{}));return;}
 if(btn.dataset.resume){resume(btn.dataset.resume);return;}
 if(btn.dataset.inspect){inspect(btn.dataset.inspect,btn.dataset.at);return;}
 if(btn.dataset.pref){const v=btn.dataset.value,p=btn.dataset.pref;if(p.startsWith('h-')){historyFilter={...historyFilter,[p.slice(2)]:v,limit:50};}else{prefs[p]=v;writeJSON(PREFS_KEY,prefs);}render();$(`[data-pref="${p}"][data-value="${CSS.escape(v)}"]`)?.focus();return;}
 if(btn.dataset.snapshot){idbGet(btn.dataset.snapshot).then(raw=>{const s=raw&&parseState(raw);s?replaceState(s,'Snapshot restored.'):toast('That snapshot could not be read.');});return;}
 const s=state.sessions[activeKey];
 if(btn.dataset.choice!==undefined&&s&&!s.revealed&&peek===null){tick();if(commit(()=>{s.choice=Number(btn.dataset.choice);s.updatedAt=Date.now();unstrike(state,s.ids[s.index],s.choice);},false)){render();$(`[data-choice="${s.choice}"]`)?.focus();}return;}
 switch(btn.dataset.action){
  case 'pause':tick();if(commit(()=>s.paused=!s.paused,false))render();break;
  case 'text':tick();detailText=!detailText;render();break;
  case 'elim':prefs.elim=!prefs.elim;writeJSON(PREFS_KEY,prefs);render();break;
  case 'timer-vis':prefs.timerHidden=!prefs.timerHidden;writeJSON(PREFS_KEY,prefs);render();break;
  case 'reader':readerOn=!readerOn;lineReader(readerOn);render();break;
  case 'reference':reference();break;
  case 'zoom-in':case 'zoom-out':{const i=Math.max(0,ZOOMS.indexOf(prefs.zoom||1)),j=Math.min(ZOOMS.length-1,Math.max(0,i+(btn.dataset.action==='zoom-in'?1:-1)));prefs.zoom=ZOOMS[j];writeJSON(PREFS_KEY,prefs);render();break;}
  case 'calc':prefs.calc=!prefs.calc;writeJSON(PREFS_KEY,prefs);render();break;
  case 'bookmark':{const id=btn.dataset.id;if(commit(()=>{state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];state.flagsAt=Date.now();})){render();toast(state.bookmarks.includes(id)?'Marked for review.':'Review mark removed.');}break;}
  case 'check':{tick();const q=byId.get(s.ids[s.index]);if(selfGraded(q)){shownSelf=q.id;render();break;}if(commit(()=>recordAnswer(state,activeKey,questions))){render();$('.explanation')?.focus({preventScroll:true});}break;}
  case 'self-right':case 'self-wrong':tick();if(commit(()=>recordAnswer(state,activeKey,questions,btn.dataset.action==='self-right'))){shownSelf=null;render();}break;
  case 'next':if(commit(()=>nextQuestion(s,questions,state.pace)))render(true);break;
  case 'peek-prev':tick();peek=Math.max(0,(peek??s.index)-1);render(true);break;
  case 'peek-next':peek=peek+1;if(!s.complete&&peek>=s.index)peek=null;else if(peek>=s.ids.length)peek=null;render(true);break;
  case 'peek-exit':peek=null;render(true);break;
  case 'peek-last':peek=s.ids.length-1;render(true);break;
  case 'retry-session':openSession({...s.options},true);break;
  case 'more':historyFilter.limit+=100;render();break;
  case 'persist':requestPersistence().then(ok=>{toast(ok?'This browser will keep your progress.':'The browser declined. Exporting backups keeps your progress safe.');fillStorage();});break;
  case 'export':tick();exportBackup();break;
  case 'sync-new':if(setSyncCode(newCode())){render();syncNow().then(()=>toast(syncStatus.state==='ok'?'Sync is on. Copy the code into your other browsers.':'Sync is on, but the first upload failed. It will retry.'));}break;
  case 'sync-join':{const code=normalizeCode($('#sync-input')?.value);if(code.length!==32){toast('That code is not complete. It has 32 letters and numbers.');break;}setSyncCode(code);render();syncNow().then(()=>{toast(syncStatus.state==='ok'?'Sync is on. Progress from both browsers is combined.':syncStatus.message);render();});break;}
  case 'sync-copy':navigator.clipboard?.writeText(formatCode(syncCode())).then(()=>toast('Sync code copied.'),()=>toast('Copy failed. Select the code and copy it.'));break;
  case 'sync-now':syncNow().then(()=>toast(syncStatus.state==='ok'?'Synced.':syncStatus.message));break;
  case 'sync-off':if(confirm('Turn off sync on this browser? Progress stays here, and other browsers keep syncing. Keep the code if you want to turn it back on.')){setSyncCode('');syncStatus={state:'idle'};render();}break;
  case 'import':$('#backup-file').click();break;}});
document.addEventListener('input',e=>{if(e.target.id!=='spr-input')return;const s=state.sessions[activeKey];if(!s||s.revealed||peek!==null)return;const v=gridIn(e.target.value);if(v!==e.target.value)e.target.value=v;s.response=v;s.updatedAt=Date.now();save();const b=$('[data-action="check"]');if(b)b.disabled=!cleanResponse(v);const pv=$('#spr-preview');if(pv)pv.innerHTML=v?`Answer preview: ${preview(v)}`:'';});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='pace'){commit(()=>state.pace=el.value);toast('Pacing preference saved for the next question.');}
 if(el.id==='backup-file'){try{const file=el.files[0];if(!file)return;if(file.size>30000000)throw Error('Backup file is too large.');const imported=parseState(await file.text());if(!imported)throw Error('This is not a valid backup for this question collection.');replaceState(imported,'Progress restored.');}catch(err){toast(err.message);}finally{el.value='';}}});
document.addEventListener('keydown',e=>{if(route.view!=='practice'||!activeKey||peek!==null||$('dialog[open]:not(#ref-dialog)')||e.target.closest('.note-pop')||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('#calc-dock')||e.target.isContentEditable||e.target.matches('select,textarea'))return;const s=state.sessions[activeKey];if(!s||s.complete)return;const typing=e.target.matches('input');
 if(!typing&&/^[a-d]$/i.test(e.key)&&!s.revealed){e.preventDefault();$(`[data-choice="${letters.indexOf(e.key.toUpperCase())}"]`)?.click();}
 else if(e.key==='Enter'&&(typing||!e.target.closest('button')||e.target.closest('[data-choice]'))){e.preventDefault();$(`[data-action="${s.revealed?'next':'check'}"]`)?.click();}});
window.addEventListener('hashchange',go);
window.addEventListener('pagehide',()=>{tick();save(true);});
// A tab coming back into view first picks up anything saved elsewhere while it was in the background.
document.addEventListener('visibilitychange',()=>{lastTick=performance.now();if(document.hidden){save(true);syncNow();return;}let raw=null;try{raw=localStorage.getItem(KEY);}catch{}if(raw!==lastRaw){absorb(raw);render();}syncNow();});
setInterval(()=>{if(!document.hidden)syncNow();},60000);window.addEventListener('online',()=>syncNow());
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue&&e.newValue!==lastRaw){const gained=absorb(e.newValue);render();if(gained)toast('Progress updated from another tab.');}});
async function init(){try{const res=await fetch('/bank/index.json');if(!res.ok)throw Error('Question collection could not be loaded.');questions=await res.json();byId=new Map(questions.map(q=>[q.id,q]));await loadState();requestPersistence();syncNow();
 if(location.hash==='#practice'&&!state.sessions[state.lastSession]?.ids)location.replace('#home');go();setInterval(tick,1000);}catch(err){$('#app').innerHTML=`<main class="loading"><h1>Let’s try that again.</h1><p>${esc(err.message)}</p><a href="/">Refresh the page</a></main>`;}}
init();
